def transform(grid):
    """Translate all non-background cells down one row, clipping at the bottom."""
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [[bg] * w for _ in range(h)]
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] != bg:
                out[r + 1][c] = grid[r][c]
    return out

def transform(grid):
    """Translate all non-background cells down one row, clipping at the bottom."""
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [[bg] * w for _ in range(h)]
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] != bg:
                out[r + 1][c] = grid[r][c]
    return out

